package com.google.javascript.jscomp;

import junit.framework.TestCase;

public class TypeCheckAI125Test extends TestCase {

  private Compiler compiler;

  @Override
  protected void setUp() throws Exception {
    super.setUp();
    compiler = new Compiler();
  }

  public void testBitwiseOperationValid() {
    CompilerOptions options = new CompilerOptions();
    options.checkTypes = true;
    compiler.init(
        new JSSourceFile[] {},
        new JSSourceFile[] { JSSourceFile.fromCode("test.js", "var x = 1 | 2;") },
        options);
    compiler.parse();
    compiler.check();
    assertEquals(0, compiler.getErrors().length);
  }

  public void testBinaryOperatorNumberValid() {
    CompilerOptions options = new CompilerOptions();
    options.checkTypes = true;
    compiler.init(
        new JSSourceFile[] {},
        new JSSourceFile[] { JSSourceFile.fromCode("test.js", "var x = 1 + 2;") },
        options);
    compiler.parse();
    compiler.check();
    assertEquals(0, compiler.getErrors().length);
  }

  public void testTypedPercentCalculation() {
    TypeCheck typeCheck = new TypeCheck(compiler, compiler.getTypeRegistry(), null);
    double percent = typeCheck.getTypedPercent();
    assertEquals(0.0, percent, 0.001);
  }
}
